import type { InjectionKey } from 'vue'
import type { RouterProviderConflict } from './setupWorkflow'

export interface ModelDescriptor {
  readonly id: string
  readonly name: string
  readonly provider: string
  readonly contextWindow: number
  readonly maxOutputTokens: number
  readonly capabilities: readonly string[]
  readonly pricing: { readonly inputPer1k: number; readonly outputPer1k: number }
  readonly source: string
  readonly reasoningFormat: string
  readonly metadata: Record<string, unknown> | null
}

export interface ProviderListError {
  readonly provider: string
  readonly kind: string
  readonly detail: string
}

export interface ModelCatalogResult {
  readonly models: readonly ModelDescriptor[]
  readonly errors: readonly ProviderListError[]
  readonly catalog?: { readonly cacheHit: boolean; readonly stale: boolean; readonly lastSyncedAt: string | null }
}

export interface ProviderDescriptor {
  readonly providerId: string
  readonly label?: string
  readonly backend?: string
  readonly providerKind?: string
  readonly runtimeSupported?: boolean
  readonly verification?: string
  readonly envKey?: string
  readonly defaultBaseUrl?: string
  readonly acceptsApiKey?: boolean
  readonly requiresApiKey?: boolean
  readonly requiresBaseUrl?: boolean
  readonly routerSupported?: boolean
  readonly deployment?: string
  readonly blocking?: boolean
  readonly canProbe?: boolean
  readonly whatYouNeed?: readonly string[]
  readonly defaultDirectModel?: string
  readonly defaultModel?: string
  readonly capabilities?: readonly string[]
  readonly fields?: readonly Record<string, unknown>[]
  readonly presets?: readonly Record<string, unknown>[]
  readonly [key: string]: unknown
}

export interface ProviderStatusRow {
  readonly providerId: string
  readonly active: boolean
  readonly configured: boolean
  readonly buildable: boolean
  readonly model: string | null
  readonly requiresApiKey: boolean
  readonly apiKeyEnv: string | null
  readonly apiKeyConfigured: boolean
  readonly apiKeyShape: string | null
  readonly baseUrlConfigured: boolean
  readonly error: string | null
  readonly modelProbe: ProviderModelProbe | null
  readonly latency: ProviderLatency | null
  readonly [key: string]: unknown
}

export interface ProviderModelProbe {
  readonly attempted: boolean
  readonly status: string
  readonly count: number
  readonly error: string | null
  readonly failureKind: string | null
}

export interface ProviderLatency {
  readonly p50TtftMs?: number | null
  readonly p95TtftMs?: number | null
  readonly samples?: number | null
  readonly windowMinutes?: number | null
}

export interface ProviderStatusResult {
  readonly activeProvider: string | null
  readonly providerResolution: Record<string, unknown>
  readonly providers: readonly ProviderStatusRow[]
  readonly count: number
  readonly [key: string]: unknown
}

export type RoutingMode = 'direct' | 'router' | 'ensemble'

export type ProviderConfigurationErrorCode =
  | 'not-found'
  | 'unsupported'
  | 'forbidden'
  | 'conflict'
  | 'unavailable'
  | 'invalid'

export class ProviderConfigurationError extends Error {
  constructor(
    readonly code: ProviderConfigurationErrorCode,
    message: string,
    readonly cause?: unknown,
    readonly details?: RouterProviderConflict,
  ) {
    super(message)
    this.name = 'ProviderConfigurationError'
  }
}

export interface ModelRoutingSnapshot {
  readonly mode: RoutingMode
  readonly provider?: string
  readonly model?: string
  readonly revision?: number
  readonly [key: string]: unknown
}

export interface ProviderCredentials {
  reveal(providerId: string, options?: { signal?: AbortSignal }): Promise<Record<string, unknown>>
  clear(providerId: string, options?: { signal?: AbortSignal }): Promise<Record<string, unknown>>
}

export interface ProviderCatalog {
  catalog(options?: { signal?: AbortSignal }): Promise<readonly ProviderDescriptor[]>
}

export interface ModelCatalog {
  list(options?: { scope?: 'active' | 'configured'; cacheOnly?: boolean; signal?: AbortSignal }): Promise<ModelCatalogResult>
  readonly capacitySupported?: boolean
  resolveCapacity?(models: readonly ModelCapacityTarget[]): Promise<{ models: ModelCapacity[] }>
}

export interface ModelCapacityFailure {
  provider: string
  model: string
  contextWindow: number
  source: ModelCapacitySource
}
export interface ModelCapacityTarget { provider: string; model: string }
export type ModelCapacitySource = 'catalog' | 'default' | 'override' | 'config'
export interface ModelCapacityLimit {
  automatic: number
  automaticSource: ModelCapacitySource
  override: number | null
  value: number
  source: ModelCapacitySource
  editable: boolean
}
export interface ModelCapacity extends ModelCapacityTarget {
  contextWindow: ModelCapacityLimit
  maxOutputTokens: ModelCapacityLimit
  localRuntime: boolean
}

export interface ProviderStatus {
  status(options?: ProviderStatusQuery): Promise<ProviderStatusResult>
}

export interface ProviderStatusQuery {
  readonly provider?: string
  readonly probeModels?: boolean
  readonly signal?: AbortSignal
}

export interface ModelRouting {
  readonly recommendationsSupported?: boolean
  recommendations?(options?: { signal?: AbortSignal }): Promise<{ plans: ModelRecommendation[] }>
  applyRecommendation?(command: RecommendationTarget, options?: { signal?: AbortSignal }): Promise<ModelRoutingSnapshot>
  acknowledgeRecommendation?(command: RecommendationTarget, options?: { signal?: AbortSignal }): Promise<{ acknowledged: boolean }>
  readonly resetRecommendedSupported?: boolean
  resetRecommended?(command: { providerId: string; activateRouter?: boolean }, options?: { signal?: AbortSignal }): Promise<ModelRoutingSnapshot>
  get(options?: { signal?: AbortSignal }): Promise<ModelRoutingSnapshot>
  setRouting(mode: RoutingMode, options?: { signal?: AbortSignal }): Promise<ModelRoutingSnapshot>
  subscribeChanged(listener: (snapshot: ModelRoutingSnapshot) => void): { close(): void }
}

export type RecommendationKind = 'router' | 'ensemble'
export interface RecommendationTarget {
  providerId: 'openrouter' | 'tokenrhythm'
  kind: RecommendationKind
  revision: string
}
export interface RecommendationRow {
  role: string
  provider: string
  model: string
  thinkingLevel: string | null
}
export interface ModelRecommendation extends RecommendationTarget {
  source: 'remote' | 'bundled'
  rows: RecommendationRow[]
  currentRows: RecommendationRow[]
  hasUpdate: boolean
  notified: boolean
}

/** Composition object retained while pages migrate to narrow domain seams. */
export interface ProviderConfiguration extends ProviderCatalog, ModelCatalog, ProviderStatus, ModelRouting {
  credentials: ProviderCredentials
}

export const PROVIDER_CONFIGURATION_KEY: InjectionKey<ProviderConfiguration> = Symbol('ProviderConfiguration')
